 public static void C06Vertical(){EditorSceneManager.OpenScene("Assets/Scenes/V2/C06_V2.unity");var room=UnityEngine.Object.FindFirstObjectByType<RoomDefinition>();float[] xs={10.3f,6.5f,10.3f,13.1f};float[] tops={10,13.1f,16,19.2f};for(int k=0;k<4;k++)B05Rooms.Block(room.transform,"Landing","V2 optional precision "+(k+3),new Vector2(xs[k],tops[k]-.25f),new Vector2(k==1?4:1.3f,.5f));UnityEngine.Object.FindFirstObjectByType<DiscoveryReward>().transform.position=new Vector2(13.1f,20);
  foreach(var sr in UnityEngine.Object.FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None))if(sr.name.StartsWith("V2 background layer")){sr.transform.position=new Vector3(10,17,sr.transform.position.z);sr.size=new Vector2(20,36);}
  var texture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Art/External/KenneyPixelPlatformer/Tilemap/tilemap-backgrounds_packed.png");var sprite=Sprite.Create(texture,new Rect(0,0,texture.width/3,texture.height),new Vector2(.5f,.5f),18);AssetDatabase.CreateAsset(sprite,"Assets/Scenes/V2/ObservationWindow.asset");for(int k=0;k<3;k++){var window=new GameObject("V2 observation window "+k);window.transform.SetParent(room.transform);window.transform.position=new Vector3(10,10+k*8,0);var sr=window.AddComponent<SpriteRenderer>();sr.sprite=sprite;sr.sortingOrder=-8;window.transform.localScale=new Vector3(2,2,1);}Save("C06");EditorApplication.Exit(0);}
 public static void Enemy(RoomDefinition room,string id,Vector2 at){var go=new GameObject("V2 "+id+" reset");go.transform.SetParent(room.transform);go.transform.position=at;go.AddComponent<EnemyReset>().prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/V2/"+id+"_V2.prefab");}
 public static void FinishArt(){var variant=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/V2/Door_V2.prefab");var instance=(GameObject)PrefabUtility.InstantiatePrefab(variant);foreach(var skin in instance.GetComponentsInChildren<V2Skin>())skin.image.sprite=B05Art.Tile(150);PrefabUtility.SaveAsPrefabAsset(instance,"Assets/Prefabs/V2/Door_V2.prefab");UnityEngine.Object.DestroyImmediate(instance);string evidence="";
  foreach(string id in B05Build.V2Ids()){EditorSceneManager.OpenScene("Assets/Scenes/V2/"+id+"_V2.unity");string before=CollisionSignature();foreach(var exit in UnityEngine.Object.FindObjectsByType<RoomExit>(FindObjectsSortMode.None)){var source=exit.GetComponent<SpriteRenderer>();if(source==null||exit.GetComponent<V2Skin>()!=null)continue;var child=new GameObject("V2 door pixels");child.transform.SetParent(exit.transform,false);var image=child.AddComponent<SpriteRenderer>();image.sprite=B05Art.Tile(150);image.sortingOrder=source.sortingOrder;var skin=exit.gameObject.AddComponent<V2Skin>();skin.source=source;skin.image=image;}
   foreach(var marker in UnityEngine.Object.FindObjectsByType<DiscoveryReward>(FindObjectsSortMode.None))marker.GetComponent<SpriteRenderer>().sprite=B05Art.Tile(151);
   var label=UnityEngine.Object.FindFirstObjectByType<RoomLabel>();label.notice=label.notice.Replace("上","↑");evidence+=(CollisionSignature()==before?"PASS":"FAIL")+" "+id+" art-only collider diff0\n";Save(id);
  }File.WriteAllText("Validation/_raw/B05/scene-art-colliders.txt",evidence);AssetDatabase.SaveAssets();EditorApplication.Exit(evidence.Contains("FAIL")?1:0);
 }
 static string CollisionSignature()=>string.Join("\n",UnityEngine.Object.FindObjectsByType<BoxCollider2D>(FindObjectsSortMode.None).OrderBy(c=>c.GetInstanceID()).Select(c=>c.GetInstanceID()+" "+c.size+" "+c.offset+" "+c.isTrigger+" "+c.transform.position+" "+c.transform.lossyScale));
 public static void Tone(char area){foreach(var sr in UnityEngine.Object.FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None)){if(sr.name.StartsWith("V2 background layer"))sr.color=area=='B'?new Color(.09f,.11f,.15f,sr.color.a):new Color(.3f,.4f,.55f,sr.color.a);if(sr.name.StartsWith("V2 support landmark")){sr.sprite=B05Art.Tile(89);sr.color=area=='B'?new Color(.8f,.5f,.25f):new Color(.55f,.72f,.9f);}}}
 public static void Save(string id){EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());File.WriteAllText("Validation/_raw/B05/"+id+"-final-author.txt","PASS new V2 Scene saved; no runtime acceptance claimed\n");}
